+struct ModuleHealthPollSuccess {
+    module_key: String,
+    event: Option<ModuleHealthEvent>,
+}
+
+async fn poll_target(
+    atlas: &mut AtlasClient,
+    consumer_id: &str,
+    svc: &VitalsServiceImpl,
+    target: &ModuleHealthPollTarget,
