+    pub fn spawn(script: &str, python_bin: &str, label: &str) -> anyhow::Result<Self> {
+        Self::spawn_with_args(script, python_bin, &[], label)
+    }
+
+    /// Spawn a Python script with extra CLI arguments (e.g. CAN port).
+    pub fn spawn_with_args(
+        script: &str,
+        python_bin: &str,
+        args: &[&str],
+        label: &str,
+    ) -> anyhow::Result<Self> {
+        let mut cmd = Command::new(python_bin);
+        cmd.arg(script);
+        for a in args {
+            cmd.arg(a);
+        }
+        let mut child = cmd
+            .stdin(Stdio::piped())
+            .stdout(Stdio::piped())
+            .stderr(Stdio::inherit())
+            .spawn()
+            .with_context(|| format!("spawn {label} script '{script}' with '{python_bin}'"))?;
+
+        let stdin = child.stdin.take().context("capture script stdin")?;
+        let stdout = child.stdout.take().context("capture script stdout")?;
+        let reader = BufReader::new(stdout);
+
+        std::thread::sleep(Duration::from_millis(100));
+        if let Some(status) = child
+            .try_wait()
+            .with_context(|| format!("check {label} startup status"))?
+        {
+            bail!("{label} script exited during startup with {status}");
+        }
+
+        Ok(Self {
+            stdin,
+            reader,
+            child,
+            label: label.to_string(),
+            alive: true,
+        })
+    }
+
+    /// Send a `{"cmd":"collect"}` request and read one JSON line back.
+    /// Returns the raw trimmed line, or `None` on any I/O error.
+    pub fn collect_json(&mut self) -> Option<String> {
+        if !self.alive {
+            return None;
+        }
+        if !self.is_alive() {
+            self.alive = false;
+            return None;
+        }
+
+        let cmd = serde_json::json!({"cmd": "collect"});
+        if let Err(e) = writeln!(self.stdin, "{cmd}") {
+            log::error!("[{}] write to script failed: {e:#}", self.label);
+            self.alive = false;
+            return None;
+        }
+        if let Err(e) = self.stdin.flush() {
+            log::error!("[{}] flush stdin failed: {e:#}", self.label);
+            self.alive = false;
+            return None;
+        }
+        let mut line = String::new();
+        match self.reader.read_line(&mut line) {
+            Ok(0) => {
+                log::warn!("[{}] script closed stdout", self.label);
+                self.alive = false;
+                return None;
+            }
+            Ok(_) => {}
+            Err(e) => {
+                log::error!("[{}] read from script failed: {e:#}", self.label);
+                self.alive = false;
+                return None;
+            }
+        }
+        let trimmed = line.trim().to_string();
+        if trimmed.is_empty() {
+            log::warn!("[{}] empty response from script", self.label);
+            return None;
+        }
+        Some(trimmed)
+    }
+
+    /// Check whether the subprocess is still running.
+    #[allow(dead_code)]
+    pub fn is_alive(&mut self) -> bool {
+        match self.child.try_wait() {
+            Ok(None) => true,
+            Ok(Some(status)) => {
+                log::warn!("[{}] script exited with {status}", self.label);
+                false
+            }
+            Err(e) => {
+                log::warn!("[{}] try_wait failed: {e:#}", self.label);
+                false
+            }
+        }
+    }
+
+    /// Replace the dead subprocess with a fresh one, preserving the original args.
+    #[allow(dead_code)]
+    pub fn restart(&mut self, script: &str, python_bin: &str, args: &[&str]) -> anyhow::Result<()> {
+        let _ = self.child.kill();
+        let _ = self.child.wait();
+
+        let mut cmd = Command::new(python_bin);
+        cmd.arg(script);
+        for a in args {
+            cmd.arg(a);
+        }
+        let mut child = cmd
+            .stdin(Stdio::piped())
+            .stdout(Stdio::piped())
+            .stderr(Stdio::inherit())
+            .spawn()
+            .with_context(|| format!("restart {} script '{script}'", self.label))?;
+
+        self.stdin = child.stdin.take().context("capture script stdin")?;
+        let stdout = child.stdout.take().context("capture script stdout")?;
+        self.reader = BufReader::new(stdout);
+        self.child = child;
+        self.alive = true;
+        Ok(())
+    }
+}

